queries:
SELECT m.Name, AVG(CAST(t.Bytes AS REAL) / t.Milliseconds) AS Rate
FROM Track t
JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId
GROUP BY m.Name;
SELECT m.Name, AVG(t.Bytes / t.Milliseconds) AS AvgRate
FROM Track t
JOIN MediaType m ON t.MediaTypeId = m.MediaTypeId
GROUP BY m.Name;
SELECT MediaType.Name, COUNT(*) FROM Track JOIN MediaType ON Track.MediaTypeId = MediaType.MediaTypeId GROUP BY MediaType.Name;
SELECT m.Name, COUNT(t.TrackId) FROM MediaType m LEFT JOIN Track t ON t.MediaTypeId = m.MediaTypeId GROUP BY m.MediaTypeId, m.Name;
